  2705  int init_threadpool(blosc2_context *context) {
  2706    int32_t tid;
  2707    int rc2;
  2708
  2709    /* Initialize mutex and condition variable objects */
  2710    pthread_mutex_init(&context->count_mutex, NULL);
  2711    pthread_mutex_init(&context->delta_mutex, NULL);
  2712    pthread_cond_init(&context->delta_cv, NULL);
  2713
  2714    /* Set context thread sentinels */
  2715    context->thread_giveup_code = 1;
  2716    context->thread_nblock = -1;
  2717
  2718    /* Barrier initialization */
  2719  #ifdef BLOSC_POSIX_BARRIERS
  2720    pthread_barrier_init(&context->barr_init, NULL, context->nthreads + 1);
  2721    pthread_barrier_init(&context->barr_finish, NULL, context->nthreads + 1);
  2722  #else
  2723    pthread_mutex_init(&context->count_threads_mutex, NULL);
  2724    pthread_cond_init(&context->count_threads_cv, NULL);
  2725    context->count_threads = 0;      /* Reset threads counter */
  2726  #endif
  2727
  2728    if (threads_callback) {
  2729        /* Create thread contexts to store data for callback threads */
  2730      context->thread_contexts = (struct thread_context *)my_malloc(
  2731              context->nthreads * sizeof(struct thread_context));
  2732      for (tid = 0; tid < context->nthreads; tid++)
  2733        init_thread_context(context->thread_contexts + tid, context, tid);
  2734    }
  2735    else {
  2736      #if !defined(_WIN32)
  2737        /* Initialize and set thread detached attribute */
  2738        pthread_attr_init(&context->ct_attr);
  2739        pthread_attr_setdetachstate(&context->ct_attr, PTHREAD_CREATE_JOINABLE);
  2740      #endif
  2741
  2742      /* Make space for thread handlers */
  2743      context->threads = (pthread_t*)my_malloc(
  2744              context->nthreads * sizeof(pthread_t));
  2745      /* Finally, create the threads */
  2746      for (tid = 0; tid < context->nthreads; tid++) {
  2747        /* Create a thread context (will destroy when finished) */
  2748        struct thread_context *thread_context = create_thread_context(context, tid);
  2749
  2750        #if !defined(_WIN32)
  2751          rc2 = pthread_create(&context->threads[tid], &context->ct_attr, t_blosc,
  2752                              (void*)thread_context);
  2753        #else
  2754          rc2 = pthread_create(&context->threads[tid], NULL, t_blosc,
  2755                              (void *)thread_context);
  2756        #endif
  2757        if (rc2) {
  2758          BLOSC_TRACE_ERROR("Return code from pthread_create() is %d.\n"
  2759                            "\tError detail: %s\n", rc2, strerror(rc2));
  2760          return (-1);
  2761        }
  2762      }
  2763    }
  2764
  2765    /* We have now started/initialized the threads */
  2766    context->threads_started = context->nthreads;
  2767    context->new_nthreads = context->nthreads;
  2768
  2769    return (0);
  2770  }
