  3052  int release_threadpool(blosc2_context *context) {
  3053    int32_t t;
  3054    void* status;
  3055    int rc;
  3056
  3057    if (context->threads_started > 0) {
  3058      if (threads_callback) {
  3059        /* free context data for user-managed threads */
  3060        for (t=0; t<context->threads_started; t++)
  3061          destroy_thread_context(context->thread_contexts + t);
  3062        my_free(context->thread_contexts);
  3063      }
  3064      else {
  3065        /* Tell all existing threads to finish */
  3066        context->end_threads = 1;
  3067        WAIT_INIT(-1, context);
  3068
  3069        /* Join exiting threads */
  3070        for (t = 0; t < context->threads_started; t++) {
  3071          rc = pthread_join(context->threads[t], &status);
  3072          if (rc) {
  3073            BLOSC_TRACE_ERROR("Return code from pthread_join() is %d\n"
  3074                              "\tError detail: %s.", rc, strerror(rc));
  3075          }
  3076        }
  3077
  3078        /* Thread attributes */
  3079        #if !defined(_WIN32)
  3080          pthread_attr_destroy(&context->ct_attr);
  3081        #endif
  3082
  3083        /* Release thread handlers */
  3084        my_free(context->threads);
  3085      }
  3086
  3087      /* Release mutex and condition variable objects */
  3088      pthread_mutex_destroy(&context->count_mutex);
  3089      pthread_mutex_destroy(&context->delta_mutex);
  3090      pthread_cond_destroy(&context->delta_cv);
  3091
  3092      /* Barriers */
  3093    #ifdef BLOSC_POSIX_BARRIERS
  3094      pthread_barrier_destroy(&context->barr_init);
  3095      pthread_barrier_destroy(&context->barr_finish);
  3096    #else
  3097      pthread_mutex_destroy(&context->count_threads_mutex);
  3098      pthread_cond_destroy(&context->count_threads_cv);
  3099      context->count_threads = 0;      /* Reset threads counter */
  3100    #endif
  3101
  3102      /* Reset flags and counters */
  3103      context->end_threads = 0;
  3104      context->threads_started = 0;
  3105    }
  3106
  3107
  3108    return 0;
  3109  }
